def solve(text: str) -> str:
    data = text.split()
    a = int(data[0])
    b = int(data[1])

    # losing positions: (floor(n*phi), floor(n*phi^2))
    loses = set()
    n = 0
    while True:
        p = (n * 5 ** 0.5 + n) / 2.0
        x = int(p)
        y = x + n
        if x > max(a, b) or y > max(a, b):
            break
        if x >= 1:
            loses.add((x, y))
        n += 1

    if (a, b) in loses:
        return 'LOSE'

    best = None
    for i in range(0, a + 1):
        for j in range(0, b + 1):
            if i == 0 and j == 0:
                continue
            if i > 0 and j > 0 and i != j:
                continue
            na, nb = a - i, b - j
            if (na, nb) in loses:
                if best is None:
                    best = (i, j)
    if best is None:
        return 'LOSE'
    return 'WIN %d %d' % best
